<script>(function(){var b=document.getElementById('menuToggle'),n=document.getElementById('siteNavigation'),o=document.getElementById('menuOverlay');if(!b||!n||!o)return;function close(){n.classList.remove('is-open');o.classList.remove('is-open');document.body.classList.remove('menu-open');b.textContent='☰';b.setAttribute('aria-expanded','false')}b.addEventListener('click',function(){var open=!n.classList.contains('is-open');n.classList.toggle('is-open',open);o.classList.toggle('is-open',open);document.body.classList.toggle('menu-open',open);b.textContent=open?'×':'☰';b.setAttribute('aria-expanded',open?'true':'false')});o.addEventListener('click',close);n.addEventListener('click',function(e){if(e.target.closest('a'))close()});document.addEventListener('keydown',function(e){if(e.key==='Escape')close()});window.addEventListener('resize',function(){if(window.innerWidth>600)close()})})();</script>
<script>(function(){document.querySelectorAll('[data-card-gallery]').forEach(function(card){var data=card.querySelector('.card-gallery-data'),image=card.querySelector('.card-gallery-image'),count=card.querySelector('.card-gallery-count');if(!data||!image)return;var images=[];try{images=JSON.parse(data.textContent||'[]')}catch(e){}var index=0;card.querySelectorAll('[data-gallery-step]').forEach(function(button){button.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();if(images.length<2)return;index=(index+Number(button.dataset.galleryStep)+images.length)%images.length;image.src=images[index];if(count)count.textContent=(index+1)+' / '+images.length})})})})();</script>
<script>(function(){var box=document.querySelector('.price-filter');if(!box)return;var min=document.getElementById('minPriceRange'),max=document.getElementById('maxPriceRange'),minOut=document.getElementById('minPriceValue'),maxOut=document.getElementById('maxPriceValue'),label=document.getElementById('priceRangeLabel'),fill=document.getElementById('priceRangeFill');var ceiling=Number(box.dataset.priceMax)||100000,step=Number(min.step)||100,fmt=new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0});function update(which){var a=Number(min.value),b=Number(max.value);if(which==='min'&&a>=b){a=Math.max(0,b-step);min.value=a}if(which==='max'&&b<=a){b=Math.min(ceiling,a+step);max.value=b}minOut.value=a>0?String(a):'';maxOut.value=b<ceiling?String(b):'';label.textContent=fmt.format(a)+' ₺ – '+(b>=ceiling?'ve üzeri':fmt.format(b)+' ₺');fill.style.left=(a/ceiling*100)+'%';fill.style.width=Math.max(0,(b-a)/ceiling*100)+'%'}min.addEventListener('input',function(){update('min')});max.addEventListener('input',function(){update('max')});update('init')})();</script>
<script>(function(){var f=[document.getElementById('filterCountry'),document.getElementById('filterCity'),document.getElementById('filterDistrict'),document.getElementById('filterNeighborhood')];if(f.some(function(x){return !x}))return;var labels=['Tüm ülkeler','Tüm şehirler','Tüm ilçeler','Tümü'];function reset(i){for(var n=i;n<4;n++)f[n].innerHTML='<option value="0">'+labels[n]+'</option>'}async function load(i,parent){reset(i);if(!parent||parent==='0')return;var r=await fetch('<?= e(app_url('/locations/children')) ?>?parent_id='+encodeURIComponent(parent));if(!r.ok)return;(await r.json()).forEach(function(x){var o=document.createElement('option');o.value=x.id;o.textContent=x.name;f[i].appendChild(o)})}f[0].addEventListener('change',function(){load(1,this.value)});f[1].addEventListener('change',function(){load(2,this.value)});f[2].addEventListener('change',function(){load(3,this.value)})})();</script><script>(function(){var input=document.getElementById('listingDestination'),list=document.getElementById('listingDestinationOptions'),selected=document.getElementById('listingLocationId'),form=input&&input.closest('form');if(!input||!list||!selected)return;var timer=null,items=[],active=-1,seq=0;function close(){list.hidden=true;list.innerHTML='';active=-1}function choose(item){input.value=item.label;selected.value=String(item.id);close();['filterCountry','filterCity','filterDistrict','filterNeighborhood'].forEach(function(id){var f=document.getElementById(id);if(f)f.value='0'});input.setCustomValidity('')}function render(rows){items=Array.isArray(rows)?rows:[];list.innerHTML='';active=-1;items.forEach(function(item){var row=document.createElement('div');row.className='location-suggestion';row.setAttribute('role','option');row.setAttribute('aria-selected','false');row.textContent=item.label;row.addEventListener('pointerdown',function(e){e.preventDefault();choose(item)});list.appendChild(row)});list.hidden=items.length===0}function search(q,id){fetch('<?= e(app_url('/locations/search')) ?>?q='+encodeURIComponent(q),{credentials:'same-origin',headers:{'Accept':'application/json'}}).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}).then(function(rows){if(id!==seq)return;render(rows)}).catch(function(){if(id===seq)close()})}input.addEventListener('input',function(){selected.value='';input.setCustomValidity('');var q=input.value.trim(),id=++seq;clearTimeout(timer);if(!q){items=[];close();return}timer=setTimeout(function(){search(q,id)},120)});input.addEventListener('focus',function(){if(items.length&&input.value.trim())list.hidden=false});input.addEventListener('keydown',function(e){if(list.hidden||!items.length)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();active=(active+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;Array.from(list.children).forEach(function(el,i){el.classList.toggle('is-active',i===active)});list.children[active].scrollIntoView({block:'nearest'})}else if(e.key==='Enter'&&active>=0){e.preventDefault();choose(items[active])}else if(e.key==='Escape')close()});input.addEventListener('change',function(){var item=items.find(function(x){return x.label===input.value});if(item)choose(item)});input.addEventListener('blur',function(){setTimeout(function(){close()},120)});['filterCountry','filterCity','filterDistrict','filterNeighborhood'].forEach(function(id){var f=document.getElementById(id);if(f)f.addEventListener('change',function(){selected.value='';input.value='';items=[];close()})});if(form)form.addEventListener('submit',function(e){if(input.value.trim()&&!selected.value){e.preventDefault();input.setCustomValidity('Lütfen açılan önerilerden bir lokasyon seçin.');input.reportValidity();input.focus()}})})();</script><script>(function(){var ci=document.querySelector('input[name="check_in"]'),co=document.querySelector('input[name="check_out"]');if(!ci||!co)return;function sync(){var d;if(ci.value){var p=ci.value.split('-');d=new Date(Number(p[0]),Number(p[1])-1,Number(p[2])+1,12,0,0)}else{d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+1)}var min=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');co.min=min;if(co.value&&co.value<min)co.value=''}ci.addEventListener('change',sync);sync()})();</script><script>(function(){document.querySelectorAll('.js-favorite-form').forEach(function(form){form.addEventListener('submit',async function(event){event.preventDefault();var button=form.querySelector('button[type="submit"]');if(!button||button.disabled)return;var oldText=button.textContent;button.disabled=true;try{var response=await fetch(form.action,{method:'POST',body:new FormData(form),credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});var data=await response.json();if(!response.ok||!data.ok)throw new Error(data.message||'Favori işlemi tamamlanamadı.');button.classList.toggle('is-active',!!data.active);button.textContent=data.active?'♥':'♡';button.setAttribute('aria-label',data.active?'Favorilerden çıkar':'Favorilere ekle');button.title=data.active?'Favorilerden çıkar':'Favorilere ekle';var status=document.getElementById('favoriteActionStatus');if(!status){status=document.createElement('div');status.id='favoriteActionStatus';status.setAttribute('role','status');status.setAttribute('aria-live','polite');status.style.cssText='position:fixed;left:50%;bottom:22px;transform:translateX(-50%);z-index:6000;padding:11px 16px;border-radius:999px;background:#20352e;color:#fff;font:600 13px system-ui;box-shadow:0 8px 24px #0002';document.body.appendChild(status)}status.textContent=data.message;status.hidden=false;clearTimeout(status._hideTimer);status._hideTimer=setTimeout(function(){status.hidden=true},2400)}catch(error){button.textContent=oldText;var msg=error.message||'Favori işlemi sırasında hata oluştu.';window.alert(msg)}finally{button.disabled=false}})})})();</script><?php \App\Core\ThemeManager::renderPartial('partials/login-modal.php', get_defined_vars()); ?></body></html>